const src = (label, url) => ({ label, url });
const BASE = [src('RESOLVE Ecoregions 2017 — catálogo y licencia CC BY 4.0', URL.resolve), src('Dinerstein et al. 2017 — artículo', URL.paper)];
const sourceGroups = {
  amazon: [...BASE, src('Science Panel for the Amazon — Assessment Report 2021', URL.amazoniaCiencia)],
  brazil: [...BASE, src('IBGE — Vegetação do Brasil', URL.ibgeVegetacao), src('MMA Brasil — biodiversidade y biomas', URL.mmaBrasil)],
  guianas: [...BASE, src('PNUD — Guiana Shield in Brief', URL.guianasPnud), src('Guyana Protected Areas Commission', URL.guyanaPac)],
  andes: [...BASE, src('MINAM Perú — Mapa Nacional de Ecosistemas', URL.peruEcosistemas), src('PNN Colombia — bosque andino y páramo', URL.colombiaParamo)],
  secoNorte: [...BASE, src('MinAmbiente Colombia — Bosque Seco Tropical', URL.colombiaSeco)],
  conoSur: [...BASE, src('Argentina — ecorregiones oficiales', URL.argentinaEco), src('Uruguay — ambientes naturales', URL.uruguayAmbientes)],
  islasChile: [...BASE, src('CONAF — Archipiélago Juan Fernández', URL.chileJuan), src('MMA Chile — Nazca-Desventuradas', URL.chileDesventuradas)],
  malpelo: [...BASE, src('PNN Colombia — Santuario de Malpelo', URL.colombiaMalpelo)],
  galapagos: [...BASE, src('Parque Nacional Galápagos — áreas protegidas', URL.galapagos)],
};

const profiles = [];
function ficha({ id, nombre, emoji, color, resumen, vegetacion, fauna, suelos, especies, ids, paises, confianza = 'alta', notas, fuentes }) {
  profiles.push({ id, nombre, emoji, color, resumen, vegetacion, fauna, suelos, saberes: [], especies, fuentes, _meta: { ecorregiones_resolve: ids, paises, confianza, notas } });
}

// Doce IDs editoriales actuales, reescritos como ecología pura. Algunos conservan dueño y otros quedan reducidos a su núcleo correcto.
ficha({ id:'selva_tropical', nombre:'Selva paranaense', emoji:'🌴', color:'#1B5E20', ids:[439], paises:['AR','BR','PY'], resumen:'Selva subtropical húmeda del Alto Paraná, con marcada estacionalidad térmica y continuidad histórica con la Mata Atlántica.', vegetacion:'Bosque multiestrato con palmito, lauráceas, lapachos, helechos arborescentes, lianas y epífitas; mosaicos con bambúseas y claros naturales.', fauna:'Yaguareté, tapir, monos caí, pavas de monte, tucanes y una gran diversidad de anfibios e invertebrados.', suelos:'Predominan suelos rojos profundos, ácidos y muy meteorizados; la estructura y la materia orgánica superficial dependen de cobertura permanente.', especies:['Yerba mate','Palmito juçara','Lapacho negro','Cedro misionero','Araucaria misionera'], fuentes:sourceGroups.brazil, notas:'ECO_ID 439 es el único que conserva este dueño. Se retiran referencias amazónicas y todo saber cultural.' });
ficha({ id:'yungas', nombre:'Yungas andinas', emoji:'🌿', color:'#2E7D32', ids:[444,460,493,504], paises:['AR','BO','PE'], resumen:'Bosques montanos húmedos de las laderas orientales andinas, ordenados en pisos altitudinales y atravesados por niebla y lluvias orográficas.', vegetacion:'Selva pedemontana, bosque montano y bosque nublado con alisos, podocarpáceas, lauráceas, helechos, epífitas y bambúes según altura.', fauna:'Oso andino, tapir de montaña, pava de monte, felinos y aves de rango altitudinal estrecho.', suelos:'Suelos de ladera húmedos, ácidos y con abundante materia orgánica superficial; alta susceptibilidad a erosión y deslizamientos cuando se pierde el dosel.', especies:['Aliso andino','Podocarpus','Cedro de montaña','Nogal criollo','Helechos arborescentes'], fuentes:sourceGroups.andes, notas:'Mantiene los cuatro ECO_ID actuales; la interfaz debe mostrar ECO_NAME porque hay gradientes regionales fuertes.' });
ficha({ id:'sabana_cerrado', nombre:'Cerrado brasileño', emoji:'🌾', color:'#8D8A20', ids:[567], paises:['BR'], resumen:'Mosaico de sabanas, campos y bosques abiertos del Brasil central, con estación seca marcada, suelos antiguos y una flora subterránea resistente al fuego.', vegetacion:'Gramíneas, arbustos retorcidos y árboles de corteza gruesa; cerradão en sitios más fértiles, campos limpios y veredas con burití en fondos húmedos.', fauna:'Lobo de crin, oso hormiguero gigante, venado campeiro, armadillos y aves de pastizal.', suelos:'Oxisoles y ultisoles profundos, muy ácidos, pobres en fósforo y a menudo ricos en aluminio; las veredas tienen suelos hidromorfos.', especies:['Pequi','Barbatimão','Burití','Ipê-amarelo','Capim-flecha'], fuentes:sourceGroups.brazil, notas:'ECO_ID 567 conserva el dueño; Llanos y sabanas guayanesas se separan.' });
ficha({ id:'chaco_seco', nombre:'Chaco seco', emoji:'🌵', color:'#8D6E63', ids:[569], paises:['AR','BO','PY'], resumen:'Llanura cálida semiárida de bosque xerófilo, con lluvias estivales irregulares y largos déficits hídricos.', vegetacion:'Quebrachales, algarrobales, mistol, palo santo, cactáceas y bromeliáceas terrestres, con abras y pastizales.', fauna:'Pecarí quimilero, tatú carreta, oso hormiguero, puma, tortuga terrestre y aves chaqueñas.', suelos:'Desde arenosos hasta arcillosos y salinos; la fertilidad puede ser moderada, pero el desmontaje expone rápidamente a erosión, compactación y salinización.', especies:['Quebracho colorado santiagueño','Algarrobo blanco','Palo santo','Mistol','Chaguar'], fuentes:[...BASE,src('Argentina — ecorregiones oficiales',URL.argentinaEco)], notas:'Conserva ECO_ID 569 y no se confunde con Chaco húmedo.' });
ficha({ id:'monte', nombre:'Monte argentino', emoji:'🏜️', color:'#A1887F', ids:[577,592], paises:['AR'], resumen:'Arbustal árido de llanuras, mesetas, sierras y bolsones dominado por jarillas y una disponibilidad de agua extremadamente pulsátil.', vegetacion:'Jarillales ralos, retamo y zampas; algarrobales y chañarales se concentran en cauces, bajos y napas accesibles.', fauna:'Guanaco, mara, zorros, piches, reptiles y aves granívoras.', suelos:'Aridisoles pedregosos o arenosos, con poca materia orgánica y frecuentes acumulaciones de sales o carbonatos.', especies:['Jarilla','Retamo','Algarrobo dulce','Chañar','Zampa'], fuentes:sourceGroups.conoSur, notas:'Conserva ECO_ID 577 y 592; el nombre RESOLVE permite distinguir Monte bajo y alto.' });
ficha({ id:'espinal', nombre:'Espinal', emoji:'🌳', color:'#9E9D24', ids:[575], paises:['AR'], resumen:'Arco de bosques abiertos, sabanas y pastizales templado-cálidos alrededor de la Pampa, con fuerte gradiente de humedad.', vegetacion:'Algarrobales, talares, caldenales, espinillares y pastizales, con composición cambiante entre norte, centro y sur.', fauna:'Ñandú, zorro gris, vizcacha, gato montés y aves de bosque abierto.', suelos:'Molisoles y suelos loésicos o arenosos; fértiles en sectores, pero vulnerables a erosión eólica, pérdida de estructura y salinización local.', especies:['Caldén','Ñandubay','Algarrobo negro','Espinillo','Tala'], fuentes:sourceGroups.conoSur, notas:'Conserva ECO_ID 575.' });
ficha({ id:'pampa', nombre:'Pampa húmeda', emoji:'🌾', color:'#7CB342', ids:[576], paises:['AR'], resumen:'Pastizal templado de relieve llano a suavemente ondulado, con alta productividad y una fuerte transformación agrícola.', vegetacion:'Gramíneas cespitosas y estoloníferas, flechillas y herbáceas; bañados y pajonales en depresiones.', fauna:'Venado de las pampas, ñandú, vizcacha, cuis y aves de pastizal.', suelos:'Molisoles profundos y fértiles con horizontes oscuros; la compactación, erosión y pérdida de carbono son los principales riesgos de uso intensivo.', especies:['Flechillas','Pasto miel','Cortadera','Chilca','Tala'], fuentes:sourceGroups.conoSur, notas:'ECO_ID 576 conserva este dueño; los campos uruguayos pasan a ficha propia.' });
ficha({ id:'puna_altoandino', nombre:'Puna central', emoji:'⛰️', color:'#8D6E63', ids:[588], paises:['AR','BO','CL','PE'], resumen:'Pastizales y matorrales altoandinos fríos, de gran amplitud térmica, radiación intensa y precipitación estacional intermedia entre la puna seca y la húmeda.', vegetacion:'Pajonales de ichu, tolares, yaretales y vegas o bofedales en depresiones húmedas.', fauna:'Vicuña, suri andino, vizcacha, flamencos y zorro culpeo.', suelos:'Suelos jóvenes, pedregosos y pobres en materia orgánica; en vegas y bofedales se acumulan horizontes orgánicos saturados que no toleran drenaje o sobrecarga.', especies:['Ichu','Tola','Yareta','Queñoa','Bofedal de Distichia'], fuentes:sourceGroups.andes, notas:'ECO_ID 588 conserva el dueño. Puna seca 587 y húmeda 589 se separan.' });
ficha({ id:'estepa_patagonica', nombre:'Estepa patagónica y altoandina austral', emoji:'🌬️', color:'#9E9E80', ids:[578,595], paises:['AR','CL'], resumen:'Estepas frías, secas y ventosas de Patagonia y la cordillera austral, con vegetación baja organizada en parches.', vegetacion:'Coironales, neneos, matas almohadilladas y arbustos bajos; mallines productivos en depresiones con agua.', fauna:'Guanaco, choique, puma, zorro colorado y aves esteparias.', suelos:'Suelos someros, pedregosos o arenosos, de baja materia orgánica; la erosión eólica aumenta cuando se rompe la cobertura.', especies:['Coirón','Neneo','Mata negra','Calafate','Molle patagónico'], fuentes:sourceGroups.conoSur, notas:'Conserva ECO_ID 578 y 595. RESOLVE 578 también cubre Malvinas/Falklands; eso exige una advertencia insular, no un segundo dueño.' });
ficha({ id:'bosque_andino_patagonico', nombre:'Bosques templados valdivianos y subpolares', emoji:'🌲', color:'#287D45', ids:[561,563], paises:['AR','CL'], resumen:'Bosques templados húmedos del sur andino, desde la selva valdiviana lluviosa hasta bosques subpolares azotados por viento y nieve.', vegetacion:'Coihues, lengas, ñires, alerces y cipreses; sotobosque denso, turberas y mosaicos con mallines y lagos glaciares.', fauna:'Huemul, pudú, huillín, monito del monte y carpintero negro.', suelos:'Andisoles y suelos jóvenes ácidos, con alta retención de agua; turberas y suelos hidromorfos son sensibles al drenaje y al fuego.', especies:['Coihue','Lenga','Alerce','Ñire','Ciprés de las Guaitecas'], fuentes:sourceGroups.conoSur, notas:'Conserva ECO_ID 561 y 563; mostrar el ECO_NAME distingue la variante magallánica de la valdiviana.' });
ficha({ id:'mediterraneo', nombre:'Matorral y bosque esclerófilo chileno', emoji:'🫒', color:'#9EAD32', ids:[596], paises:['CL'], resumen:'Ecosistema mediterráneo de Chile central, con lluvias invernales y una sequía estival prolongada.', vegetacion:'Bosque y matorral esclerófilo con quillay, peumo, boldo, litre y espino; suculentas y herbáceas anuales en sitios secos.', fauna:'Zorro culpeo, degú, cururo, tenca, reptiles y polinizadores endémicos.', suelos:'Suelos variables y a menudo delgados en laderas; la pérdida de cubierta agrava erosión, escorrentía e incendios severos.', especies:['Quillay','Peumo','Boldo','Litre','Espino'], fuentes:[...BASE,src('MMA Chile — clasificación de ecosistemas terrestres', 'https://clasificacionespecies.mma.gob.cl/ecosistemas-terrestres/descarga-de-informacion/atlas-ecosistemas-terrestres-2/'),src('CONAF — vegetación y áreas protegidas','https://www.conaf.cl/parques-nacionales/')], notas:'Conserva ECO_ID 596.' });
ficha({ id:'desierto_costero', nombre:'Desiertos costeros de Atacama y Sechura', emoji:'🌫️', color:'#C8B7A6', ids:[598,608], paises:['CL','PE'], resumen:'Desiertos hiperáridos de la costa del Pacífico, donde nieblas, ríos alóctonos y episodios lluviosos sostienen focos discontinuos de vida.', vegetacion:'Cobertura muy rala; lomas de niebla, tillandsiales, cactáceas y vegetación de oasis, quebradas o salares.', fauna:'Zorro costeño, guanaco en lomas, lagartijas, aves marinas y fauna de humedales aislados.', suelos:'Aridisoles minerales, salinos y con materia orgánica mínima; costras y depósitos eólicos se alteran con facilidad.', especies:['Tillandsia de lomas','Tamarugo','Cactáceas columnares','Amancay de lomas','Grama salada'], fuentes:sourceGroups.andes, notas:'Conserva ECO_ID 598 y 608; no confundir las lomas con vegetación alimentada por lluvia regular.' });

// Fichas nuevas: partición ecológica de selva_tropical y cobertura de huecos continentales.
ficha({ id:'mata_araucaria_altura', nombre:'Bosque de araucaria de la Mata Atlántica', emoji:'🌲', color:'#245F3A', ids:[440], paises:['AR','BR'], resumen:'Bosque húmedo subtropical de planaltos frescos, dominado por araucaria brasileña y mezclado con lauráceas y mirtáceas.', vegetacion:'Dosel emergente de Araucaria angustifolia sobre bosque siempreverde o semideciduo, con yerba mate, imbuia, helechos y bambúes.', fauna:'Papagayo charao, yacutinga, mono aullador, felinos y pequeños mamíferos consumidores de piñones.', suelos:'Suelos profundos, ácidos y arcillosos derivados de basaltos; alta materia orgánica superficial bajo clima húmedo y fresco.', especies:['Araucaria brasileña','Yerba mate','Imbuia','Xaxim','Guabiroba'], fuentes:sourceGroups.brazil, notas:'Reemplaza selva_tropical para ECO_ID 440; conserva identidad de bosque mixto de altura.' });
ficha({ id:'mata_atlantica_restingas', nombre:'Restingas atlánticas', emoji:'🏝️', color:'#4E8D67', ids:[441,485], paises:['BR'], resumen:'Mosaico costero sobre arenas cuaternarias sometido a sal, viento, sequía edáfica e inundación local.', vegetacion:'Herbazales de dunas, matorrales, bromeliales y bosques bajos; la estructura cambia en pocos metros con relieve y nivel freático.', fauna:'Lagartijas, anfibios de charcas temporarias, aves costeras y pequeños mamíferos endémicos o restringidos.', suelos:'Arenas muy permeables, ácidas y pobres en nutrientes; podzoles y depresiones orgánicas o anegables aparecen detrás de cordones dunares.', especies:['Clusia','Aechmea','Ipomoea pes-caprae','Guapira','Cereus fernambucensis'], fuentes:sourceGroups.brazil, notas:'Reemplaza selva_tropical en 441 y 485; la restinga no es bosque de tierra firme.' });
ficha({ id:'mata_atlantica_costera', nombre:'Bosques húmedos costeros de la Mata Atlántica', emoji:'🌧️', color:'#126A43', ids:[442,491,500], paises:['BR'], resumen:'Bosques tropicales húmedos entre costa y sierras orientales de Brasil, con lluvia oceánica, fuerte gradiente altitudinal y alto endemismo.', vegetacion:'Bosque ombrófilo denso con palmeras, lauráceas, mirtáceas, lianas, bromelias y orquídeas; niebla frecuente en laderas altas.', fauna:'Muriquis, tamarinos, perezosos, tucanes, jacutingas y numerosos anfibios endémicos.', suelos:'Suelos muy meteorizados y ácidos, a menudo someros en laderas; la cobertura protege contra erosión intensa bajo lluvias abundantes.', especies:['Palmito juçara','Jequitibá','Pau-brasil','Embaúba','Bromelias'], fuentes:sourceGroups.brazil, notas:'Agrupa 442, 491 y 500; siempre mostrar ECO_NAME para distinguir Bahía, Pernambuco y Serra do Mar.' });
ficha({ id:'mata_atlantica_interior', nombre:'Bosques interiores de la Mata Atlántica', emoji:'🌳', color:'#397A3E', ids:[443,492], paises:['BR'], resumen:'Bosques estacionales del interior nordestino, más secos y fragmentados que la franja atlántica costera.', vegetacion:'Bosque semideciduo a deciduo con dosel más abierto, lianas y transiciones hacia caatinga y cerrados.', fauna:'Puma, margay, monos, pecaríes y aves forestales que dependen de corredores entre fragmentos.', suelos:'Suelos profundos pero variables, desde latosoles ácidos hasta terrenos más fértiles; la estación seca y la fragmentación elevan el riesgo de fuego.', especies:['Pau-d’arco','Jatobá','Jequitibá','Sucupira','Barriguda'], fuentes:sourceGroups.brazil, notas:'Reemplaza selva_tropical en 443 y 492.' });
ficha({ id:'amazonia_noroccidental_tierra_firme', nombre:'Amazonía noroccidental de tierra firme', emoji:'🌳', color:'#0B6B3A', ids:[446,473,483,503], paises:['BR','CO','EC','PE'], resumen:'Selvas siempreverdes de tierra firme del piedemonte y las cuencas de Caquetá, Napo, Japurá y Solimões, sin inundación fluvial anual generalizada.', vegetacion:'Dosel alto y multiestrato con palmeras, leguminosas, lianas y epífitas; mosaicos de colinas, terrazas y bosques de piedemonte.', fauna:'Jaguar, danta amazónica, monos lanudos, águila harpía, guacamayos y una diversidad excepcional de anfibios y peces de cabeceras.', suelos:'Predominan ultisoles y oxisoles ácidos y pobres; terrazas jóvenes y piedemontes pueden ser más fértiles. La biomasa y la hojarasca concentran nutrientes.', especies:['Ceiba','Ungurahua','Castaña amazónica','Cedro','Palmas de dosel'], fuentes:sourceGroups.amazon, notas:'Reemplaza selva_tropical en 446, 473, 483 y 503. Excluye várzeas e igapós.' });
ficha({ id:'amazonia_suroccidental_tierra_firme', nombre:'Amazonía suroccidental de tierra firme', emoji:'🌴', color:'#176F3B', ids:[474,497,505,512], paises:['BO','BR','PE'], resumen:'Selvas de tierra firme del arco suroccidental amazónico, con fuerte gradiente de estacionalidad y grandes ríos pero extensas superficies no inundables.', vegetacion:'Bosques altos con palmeras, bambusales de Guadua en sectores occidentales y transiciones a bosques estacionales hacia el sur.', fauna:'Jaguar, pecarí labiado, lobo de río, monos, guacamayos y águila harpía.', suelos:'Suelos meteorizados y ácidos, con parches jóvenes de origen andino; la compactación y la erosión aumentan tras desmontes y caminos.', especies:['Castaña amazónica','Shihuahuaco','Bambú Guadua','Caoba','Aguaje'], fuentes:sourceGroups.amazon, notas:'Reemplaza selva_tropical en 474, 497, 505 y 512.' });
ficha({ id:'amazonia_oriental_tierra_firme', nombre:'Amazonía oriental y meridional de tierra firme', emoji:'🌴', color:'#2B7338', ids:[476,507,508,518], paises:['BR'], resumen:'Selvas de tierra firme entre Madeira, Tapajós, Xingu, Tocantins y Pindaré, con una estación seca creciente hacia el arco sur y oriental.', vegetacion:'Bosques altos siempreverdes a estacionales, lianas y palmeras; enclaves abiertos y transiciones hacia cerrado y bosques secos.', fauna:'Jaguar, tapir, monos araña y capuchinos, águila harpía, guacamayos y tortugas terrestres.', suelos:'Latosoles y argisoles antiguos, ácidos y pobres; el déficit estacional incrementa vulnerabilidad a incendios antrópicos.', especies:['Castaña amazónica','Ipê','Angelim','Babaçu','Copaíba'], fuentes:sourceGroups.amazon, notas:'Reemplaza selva_tropical en 476, 507, 508 y 518; ECO_NAME sigue visible por diferencias entre interfluvios.' });
ficha({ id:'varzeas_igapos_amazonicos', nombre:'Várzeas e igapós amazónicos', emoji:'🌊', color:'#147D71', ids:[467,469,480,482,496], paises:['BR','CO','PE'], resumen:'Bosques y humedales sometidos al pulso anual de inundación de ríos amazónicos; la duración, profundidad y química del agua organizan el paisaje.', vegetacion:'Bosques inundables, palmares, lagos, gramalotes y vegetación flotante. Las várzeas de aguas blancas son más fértiles que los igapós de aguas negras.', fauna:'Manatí amazónico, delfines de río, caimanes, capibaras, peces migratorios, aves acuáticas y primates ribereños.', suelos:'Sedimentos aluviales jóvenes y relativamente fértiles en várzea; arenas y suelos muy pobres y ácidos en igapó. El drenaje artificial rompe el pulso ecológico.', especies:['Aguaje','Açaí','Camu-camu','Victoria amazónica','Kapok de várzea'], fuentes:sourceGroups.amazon, notas:'Reemplaza selva_tropical en cinco ECO_ID inundables. La ficha conserva la distinción várzea/igapó en el texto.' });
ficha({ id:'guayanas_bosques_tierras_bajas', nombre:'Bosques de tierras bajas del Escudo Guayanés', emoji:'🌳', color:'#075B3A', ids:[465,466,484,511], paises:['BR','GF','GY','SR','VE'], resumen:'Bosques húmedos sobre geología muy antigua del Escudo Guayanés y cuencas Negro–Branco, con endemismo elevado y extensas áreas continuas.', vegetacion:'Bosques altos siempreverdes, palmares y bosques de piedemonte; especies de madera densa y mosaicos sobre arenas blancas o rocas precámbricas.', fauna:'Jaguar, tapir, gallito de las rocas, águila harpía, monos y una ictiofauna muy diversa.', suelos:'Suelos extremadamente meteorizados, ácidos y oligotróficos; arenas blancas y afloramientos generan mosaicos edáficos de baja resiliencia.', especies:['Greenheart','Wallaba','Mora','Balatá','Palmas Euterpe'], fuentes:sourceGroups.guianas, notas:'Reemplaza selva_tropical en 465, 466, 484 y 511.' });
ficha({ id:'guayanas_bosques_inundables_delta', nombre:'Bosques inundables de Guayanas y delta del Orinoco', emoji:'💧', color:'#126F62', ids:[463,488], paises:['GF','GY','SR','VE'], resumen:'Pantanos forestados y bosques deltaicos de muy baja pendiente, controlados por inundación dulce, mareas y sedimentos costeros.', vegetacion:'Palmares pantanosos, bosques de pantano, herbazales y transiciones a manglar; canales y diques naturales producen mosaicos finos.', fauna:'Manatí antillano y amazónico según cuenca, nutria gigante, caimanes, ibis, garzas y peces estuarinos.', suelos:'Suelos hidromorfos, arcillosos u orgánicos, con anoxia prolongada; salinidad variable cerca de estuarios.', especies:['Mora excelsa','Euterpe oleracea','Mauritia flexuosa','Pterocarpus officinalis','Heliconias'], fuentes:sourceGroups.guianas, notas:'ECO_ID 463 sale de selva_tropical y se une con 488, que era un vacío.' });
ficha({ id:'pantepui_guayana_alta', nombre:'Pantepui y tierras altas guayanesas', emoji:'⛰️', color:'#3D6950', ids:[464,490], paises:['BR','CO','GY','SR','VE'], resumen:'Montañas y mesetas de arenisca aisladas sobre el Escudo Guayanés, con gradientes abruptos, nubes frecuentes y altísimo endemismo.', vegetacion:'Bosques montanos, matorrales, turberas, sabanas de altura y vegetación rupícola; cada tepuy funciona como isla biogeográfica.', fauna:'Gallito de las rocas, ranas y lagartijas endémicas, pequeños mamíferos y aves de montaña.', suelos:'Suelos someros, ácidos y extremadamente pobres sobre areniscas; turberas locales almacenan agua y carbono.', especies:['Heliamphora','Bonnetia','Stegolepis','Brocchinia','Orquídeas tepuyanas'], fuentes:sourceGroups.guianas, notas:'Reemplaza selva_tropical en 464 y agrega 490. No divulgar ubicaciones de especies raras.' });
ficha({ id:'campinaranas_aguas_negras', nombre:'Campinaranas del río Negro', emoji:'🌿', color:'#557A45', ids:[498], paises:['BR','CO','VE'], resumen:'Mosaicos de bosque bajo, matorral y sabana amazónica sobre arenas blancas extremadamente pobres y a menudo encharcadas.', vegetacion:'Campinarana forestada, arbustiva y gramíneo-leñosa con dosel bajo, raíces superficiales y flora especializada.', fauna:'Aves restringidas a arenas blancas, primates y pequeños vertebrados; alta especialización local.', suelos:'Espodosoles arenosos, muy ácidos y oligotróficos, con acumulación subsuperficial de materia orgánica y aluminio; son muy sensibles al tránsito y al fuego.', especies:['Macucu','Caraipa','Mauritia','Orquídeas de arena blanca','Bromelias terrestres'], fuentes:[...sourceGroups.amazon,src('IBGE — campinarana y suelos arenosos',URL.ibgeCampinarana)], notas:'Reemplaza selva_tropical en ECO_ID 498.' });
ficha({ id:'caatinga_enclaves_humedos', nombre:'Enclaves húmedos de la Caatinga', emoji:'🌳', color:'#4F7D3B', ids:[445], paises:['BR'], resumen:'Islas de bosque húmedo o subhúmedo sobre sierras del Nordeste brasileño, rodeadas por la matriz semiárida de Caatinga.', vegetacion:'Bosques montanos y brejos de altitude con elementos atlánticos y amazónicos, epífitas y cursos de agua más persistentes.', fauna:'Aves forestales aisladas, pequeños mamíferos, anfibios y reptiles con endemismos locales.', suelos:'Más profundos y húmedos que la matriz semiárida, pero a menudo inclinados y erosivos; funcionan como refugios climáticos.', especies:['Bromelias','Orquídeas','Jatobá','Ingá','Helechos'], fuentes:sourceGroups.brazil, notas:'Agrega ECO_ID 445; no confundir con Caatinga seca 525.' });
ficha({ id:'bosques_montanos_andes_norte', nombre:'Bosques montanos de los Andes del norte', emoji:'🌫️', color:'#2C7250', ids:[448,457,477,486,513], paises:['CO','EC','VE'], resumen:'Bosques nublados y montanos de las cordilleras septentrionales, fragmentados naturalmente por valles y con enorme recambio de especies con la altura.', vegetacion:'Lauráceas, encenillos, palmas de cera, podocarpáceas, helechos arborescentes, bambúes y abundantes epífitas.', fauna:'Oso andino, danta de montaña, puma, gallito de roca, tucanes andinos y numerosos anfibios endémicos.', suelos:'Andisoles e inceptisoles húmedos, ricos en materia orgánica pero inestables en pendientes; la niebla aporta agua adicional.', especies:['Palma de cera','Encenillo','Podocarpus','Aliso andino','Quina'], fuentes:sourceGroups.andes, notas:'Agrega cinco ECO_ID montanos de Colombia, Ecuador y Venezuela.' });
ficha({ id:'montanas_caribe_norte', nombre:'Montañas húmedas del Caribe suramericano', emoji:'⛰️', color:'#347558', ids:[456,499], paises:['CO','VE'], resumen:'Bosques montanos aislados de la Cordillera de la Costa venezolana y Sierra Nevada de Santa Marta, con gradientes desde el Caribe seco hasta cumbres nubladas.', vegetacion:'Bosques siempreverdes montanos, palmares, helechos, epífitas y parches de bosque achaparrado en crestas.', fauna:'Puma, mono aullador, paujiles, colibríes y anfibios de distribución muy restringida.', suelos:'Suelos húmedos de montaña, someros en laderas y con acumulación orgánica bajo niebla; alta susceptibilidad a movimientos en masa.', especies:['Palma de cera','Podocarpus','Cedro de montaña','Bromelias','Lauráceas'], fuentes:sourceGroups.andes, notas:'Agrega 456 y 499; el aislamiento exige mostrar ECO_NAME.' });
ficha({ id:'bosques_humedos_caribe_colombia_venezuela', nombre:'Bosques húmedos del Caribe colombiano y Catatumbo', emoji:'🌧️', color:'#287B49', ids:[447,478], paises:['CO','VE'], resumen:'Bosques húmedos de tierras bajas y piedemontes del Catatumbo, Magdalena y Urabá, entre Andes y Caribe.', vegetacion:'Bosques altos con palmeras, ceibas, leguminosas, lianas y humedales ribereños; transiciones rápidas hacia bosque seco.', fauna:'Jaguar, tapir, mono araña, paujiles, tucanes y anfibios tropicales.', suelos:'Aluviales jóvenes en valles y suelos meteorizados en colinas; drenaje y fertilidad varían mucho con terraza y río.', especies:['Ceiba','Cativo','Caracolí','Palma milpesos','Cedro'], fuentes:[...BASE,src('PNN Colombia — sistema de áreas y ecosistemas','https://www.parquesnacionales.gov.co/')], notas:'Agrega 447 y 478. No reemplaza Chocó-Darién 454, reservado en la entrega anterior.' });
ficha({ id:'bosque_humedo_occidente_ecuador', nombre:'Bosques húmedos del occidente ecuatoriano', emoji:'🌴', color:'#1F7A4D', ids:[516], paises:['EC'], resumen:'Bosques tropicales húmedos y subhúmedos al oeste de los Andes ecuatorianos, con alta diversidad y transición hacia Chocó y bosques secos tumbesinos.', vegetacion:'Dosel alto con palmeras, ceibas, lauráceas, lianas y epífitas; bosques semideciduos en el extremo más estacional.', fauna:'Mono araña de cabeza café, jaguar, tucanes, anfibios y aves endémicas del Chocó-Tumbes.', suelos:'Suelos arcillosos y muy meteorizados en colinas; aluviales en llanuras. Las lluvias intensas y pendientes elevan riesgo de erosión.', especies:['Tagua','Balsa','Ceibo','Guayacán','Palma real'], fuentes:[...BASE,src('MAATE Ecuador — Socio Bosque',URL.ecuadorBosque)], notas:'Agrega ECO_ID 516.' });
ficha({ id:'valles_secos_interandinos', nombre:'Valles secos interandinos', emoji:'🏜️', color:'#A17448', ids:[479,523,526,538,542], paises:['BO','CO','PE'], resumen:'Bosques secos y matorrales encerrados entre cordilleras, con fuerte sombra de lluvia, ríos estacionales y elevado endemismo.', vegetacion:'Bosque deciduo bajo, cactáceas, acacias, molles y matorral espinoso; franjas ribereñas contrastan con laderas secas.', fauna:'Venados, zorros, felinos pequeños, loros, colibríes y reptiles adaptados a calor y sequía.', suelos:'Suelos pedregosos o aluviales, frecuentemente someros y erosionables; salinidad local en fondos cerrados.', especies:['Molle','Tara','Ceiba','Prosopis','Cactáceas columnares'], fuentes:[...sourceGroups.andes,src('MinAmbiente Colombia — Bosque Seco Tropical',URL.colombiaSeco)], notas:'Prioridad 1. Agrupa Marañón, valles secos bolivianos, Cauca, Magdalena y Patía; ECO_NAME debe permanecer visible.' });
ficha({ id:'bosques_secos_caribe_colombia_venezuela', nombre:'Bosques secos del Caribe suramericano y Orinoquía occidental', emoji:'🌵', color:'#9A7440', ids:[520,536,539,546], paises:['CO','VE'], resumen:'Bosques tropicales deciduos y matorrales estacionales de llanuras interiores y cuencas caribeñas, con sequía anual marcada.', vegetacion:'Bosque bajo a mediano que pierde hojas, cardonales, espinares, palmares y bosques ribereños persistentes.', fauna:'Venado cola blanca, pecarí, ocelote, iguanas, guacamayas y aves de bosque seco.', suelos:'Suelos desde aluviales relativamente fértiles hasta arcillosos y salinos; alta erosión al retirar cobertura durante la estación seca.', especies:['Dividivi','Caracolí','Ceiba','Cují','Guayacán'], fuentes:sourceGroups.secoNorte, notas:'Agrega Apure–Villavicencio, Lara–Falcón, Maracaibo y Sinú. Guajira xerófila queda aparte.' });
ficha({ id:'bosques_secos_tumbes_ecuador_peru', nombre:'Bosques secos de Tumbes, Piura y Ecuador', emoji:'🌳', color:'#A57A3D', ids:[531,549], paises:['EC','PE'], resumen:'Bosques deciduos del Pacífico ecuatorial sometidos a una estación seca prolongada y lluvias muy variables asociadas a El Niño.', vegetacion:'Ceibales, algarrobales, guayacanes y matorral espinoso; el dosel reverdece rápidamente con las lluvias.', fauna:'Zorro de Sechura, venado cola blanca, mono aullador de la costa, perico macareño y aves endémicas tumbesinas.', suelos:'Suelos secos y a menudo pedregosos o arcillosos; abanicos y valles aluviales son más profundos, pero susceptibles a erosión torrencial.', especies:['Ceibo','Algarrobo peruano','Guayacán','Palo santo','Hualtaco'], fuentes:[...sourceGroups.andes,src('MinAmbiente Colombia — referencia regional de bosque seco tropical',URL.colombiaSeco)], notas:'Agrega 531 y 549; no mezclar con desierto de Sechura 608.' });
ficha({ id:'caatinga', nombre:'Caatinga', emoji:'🌵', color:'#AA7D43', ids:[525], paises:['BR'], resumen:'Bosque y matorral semiárido exclusivamente brasileño, regido por lluvias escasas e irregulares y sequías plurianuales.', vegetacion:'Bosque bajo deciduo, cactáceas, bromelias terrestres y arbustos espinosos; muchas plantas rebrotan o almacenan agua.', fauna:'Guacamayo de Lear, armadillos, mocó, zorro cangrejero y reptiles del sertão.', suelos:'Muy variables y a menudo someros sobre roca cristalina; fertilidad local moderada, pero baja infiltración y erosión intensa en superficies desnudas.', especies:['Mandacaru','Umbuzeiro','Juazeiro','Xique-xique','Aroeira-do-sertão'], fuentes:sourceGroups.brazil, notas:'Prioridad 1. Agrega ECO_ID 525 y se mantiene separada de enclaves húmedos 445.' });
ficha({ id:'mata_atlantica_seca', nombre:'Bosques secos atlánticos de Brasil', emoji:'🍂', color:'#8E7940', ids:[524], paises:['BR'], resumen:'Bosques estacionales deciduos del interior oriental de Brasil, en contacto con Caatinga, Cerrado y Mata Atlántica húmeda.', vegetacion:'Dosel mediano que pierde gran parte de sus hojas, árboles de madera densa, lianas y cactáceas en afloramientos.', fauna:'Muriquis y primates localmente, felinos, pecaríes, armadillos y aves de bosque estacional.', suelos:'Suelos más fértiles que muchos bosques húmedos vecinos, a menudo sobre calizas; muy expuestos a erosión tras la deforestación.', especies:['Aroeira','Angico','Barriguda','Ipê-roxo','Cereus'], fuentes:sourceGroups.brazil, notas:'Agrega ECO_ID 524.' });
ficha({ id:'bosque_seco_chiquitano', nombre:'Bosque seco chiquitano', emoji:'🌳', color:'#7A7134', ids:[529], paises:['BO','BR'], resumen:'Gran bosque estacional de transición entre Amazonía, Cerrado y Chaco, con estación seca marcada y un dosel todavía continuo.', vegetacion:'Bosques semideciduos con tajibo, cuchi, curupaú y soto; afloramientos rocosos y sabanas intercaladas.', fauna:'Jaguar, tapir, pecarí, armadillo gigante, pavas y guacamayos.', suelos:'Suelos antiguos y variables, desde rojos profundos hasta someros sobre roca; el fuego repetido simplifica el bosque.', especies:['Tajibo','Cuchi','Curupaú','Soto','Cuta'], fuentes:[...BASE,src('MMA Brasil — biomas y transiciones',URL.mmaBrasil)], notas:'Agrega ECO_ID 529. No es una extensión del Chaco seco.' });
ficha({ id:'bosque_seco_mato_grosso', nombre:'Bosques estacionales del Mato Grosso', emoji:'🍂', color:'#6F7430', ids:[481], paises:['BR'], resumen:'Bosques tropicales estacionales del sur amazónico, en la transición con Cerrado, sometidos a una estación seca creciente.', vegetacion:'Bosque semideciduo alto con lianas, palmeras y especies amazónicas mezcladas con elementos del Cerrado.', fauna:'Jaguar, tapir, pecarí, monos y aves forestales del arco sur amazónico.', suelos:'Latosoles y argisoles ácidos; la sequía estacional vuelve al bosque especialmente vulnerable a incendios de borde.', especies:['Copaíba','Ipê','Jatobá','Castanha-do-pará','Babaçu'], fuentes:sourceGroups.brazil, notas:'Agrega ECO_ID 481; RESOLVE lo ubica en bioma húmedo pese al nombre dry forests.' });
ficha({ id:'bosques_babacu_maranhao', nombre:'Bosques de babaçu de Maranhão', emoji:'🌴', color:'#6F8535', ids:[540], paises:['BR'], resumen:'Mosaico de bosque estacional y palmares de babaçu en la transición entre Amazonía, Cerrado y Caatinga.', vegetacion:'Palmares densos de babaçu, bosques secundarios, capoeiras y remanentes semideciduos; la palma coloniza claros y áreas perturbadas.', fauna:'Monos, armadillos, pecaríes, aves frugívoras y polinizadores de mosaicos forestales.', suelos:'Suelos generalmente ácidos y meteorizados, con fertilidad variable; la cobertura de palmar protege pero no sustituye la diversidad del bosque maduro.', especies:['Babaçu','Jatobá','Ipê','Bacuri','Burití'], fuentes:sourceGroups.brazil, notas:'Agrega ECO_ID 540. El conocimiento de quebradeiras va sólo en la capa territorial.' });
ficha({ id:'sabanas_guayanesas', nombre:'Sabanas del Escudo Guayanés', emoji:'🌾', color:'#8A9B3A', ids:[570], paises:['BR','GY','SR','VE'], resumen:'Extensas sabanas tropicales sobre el Escudo Guayanés, interrumpidas por bosques de galería, humedales y serranías.', vegetacion:'Pastizales, sabanas arbustivas, morichales y bosques ribereños; la humedad del suelo y el fuego producen mosaicos.', fauna:'Oso hormiguero gigante, venado, jaguar, armadillos, aves de pastizal y peces de cabeceras.', suelos:'Suelos viejos, ácidos y pobres, a menudo arenosos; depresiones estacionales presentan hidromorfía.', especies:['Trachypogon','Moriche','Curatella americana','Byrsonima','Axonopus'], fuentes:sourceGroups.guianas, notas:'Reemplaza sabana_cerrado para ECO_ID 570; no trasladar prácticas del Cerrado brasileño.' });
ficha({ id:'llanos_orinoquia', nombre:'Llanos del Orinoco', emoji:'🌾', color:'#93A83B', ids:[572], paises:['CO','VE'], resumen:'Sabanas tropicales de la cuenca del Orinoco con alternancia anual entre sequía e inundación y grandes gradientes de drenaje.', vegetacion:'Pastizales abiertos, sabanas arboladas, morichales, esteros y bosques de galería; bancos, bajos y esteros sostienen comunidades distintas.', fauna:'Chigüiro, venado de cola blanca, oso hormiguero, caimán del Orinoco, anaconda y grandes bandadas de aves acuáticas.', suelos:'Predominan suelos ácidos y pobres; planicies aluviales alternan anoxia e intensa desecación, mientras bancos elevados drenan mejor.', especies:['Moriche','Chaparra','Samán','Trachypogon','Palma llanera'], fuentes:[...BASE,src('FAO Colombia — pesca artesanal en Orinoco y Amazonía',URL.pescaColombia)], notas:'Reemplaza sabana_cerrado para ECO_ID 572.' });
ficha({ id:'sabanas_beni', nombre:'Sabanas inundables del Beni', emoji:'💧', color:'#6D9E54', ids:[565], paises:['BO','BR','PE'], resumen:'Mosaico de sabanas, islas de bosque y humedales estacionales en las planicies de los Llanos de Moxos y alto Madeira.', vegetacion:'Pastizales inundables, palmares, bosques de galería e islas forestales sobre microrelieves elevados.', fauna:'Ciervo de los pantanos, paraba barba azul, londra, capibara, caimanes y aves acuáticas.', suelos:'Suelos aluviales hidromorfos con ciclos de anegamiento y sequía; pequeñas diferencias de cota controlan oxígeno y vegetación.', especies:['Palma motacú','Tajibo','Patujú','Gramíneas de inundación','Victoria boliviana'], fuentes:[...BASE,src('Science Panel for the Amazon — humedales amazónicos',URL.amazoniaCiencia)], notas:'Agrega ECO_ID 565. El manejo de montículos prehispánicos requiere investigación territorial propia.' });
ficha({ id:'campos_rupestres', nombre:'Campos rupestres de Espinhaço', emoji:'🌼', color:'#778A4A', ids:[566], paises:['BR'], resumen:'Sabanas montanas y afloramientos rocosos de las sierras brasileñas, con suelos mínimos, nacientes y excepcional endemismo vegetal.', vegetacion:'Pastizales rupestres, matorrales, rosetas, siemprevivas, orquídeas y bromelias entre cuarcitas y arenas.', fauna:'Lobo de crin, pequeños mamíferos, colibríes, anfibios de cabeceras y numerosos polinizadores.', suelos:'Muy someros, arenosos, ácidos y oligotróficos; turberas de nacientes y grietas húmedas concentran materia orgánica.', especies:['Sempre-vivas','Vellozia','Lychnophora','Paepalanthus','Orquídeas rupestres'], fuentes:[...sourceGroups.brazil,src('FAO GIAHS — sistema del Espinhaço Meridional',URL.giahsEspinhaco)], notas:'Agrega ECO_ID 566. No publicar sitios exactos de recolección de flora.' });
ficha({ id:'campos_uruguayos', nombre:'Campos y pastizales uruguayos', emoji:'🌾', color:'#77A84B', ids:[574], paises:['AR','BR','UY'], resumen:'Pastizales subtropicales del Uruguay, sur de Brasil y noreste argentino, con mosaicos de campo, palmares, serranías y bosques ribereños.', vegetacion:'Gramíneas C3 y C4, hierbas, pajonales, palmares de butiá y bosques de quebrada o galería.', fauna:'Venado de campo, ñandú, mulita, zorro de campo y aves como capuchinos y tero.', suelos:'Muy heterogéneos: profundos sobre basalto o sedimentos, someros en sierras y arenosos en costas; la cobertura permanente es clave.', especies:['Paspalum','Andropogon','Flechillas','Butiá','Carqueja'], fuentes:sourceGroups.conoSur, notas:'Reemplaza pampa para ECO_ID 574; no asumir suelo pampeano profundo en todo el polígono.' });
ficha({ id:'chaco_humedo', nombre:'Chaco húmedo', emoji:'🌴', color:'#4F8A45', ids:[571], paises:['AR','BR','PY'], resumen:'Llanura subtropical más lluviosa que el Chaco seco, con bosques, sabanas de palmeras, esteros y lagunas sometidos a pulsos de inundación.', vegetacion:'Quebrachales húmedos, palmares de caranday, pajonales, selvas en galería y vegetación acuática.', fauna:'Carpincho, yacaré, aguará guazú, mono carayá, tapir, pecaríes y gran diversidad de aves acuáticas.', suelos:'Arcillosos y aluviales, con drenaje impedido, sodicidad o salinidad en bajos; alternan saturación y contracción estacional.', especies:['Quebracho colorado chaqueño','Caranday','Urunday','Palo piedra','Paja amarilla'], fuentes:[...sourceGroups.conoSur,src('Argentina — Chaco Húmedo',URL.argentinaChaco)], notas:'Prioridad 1. Agrega ECO_ID 571 y queda explícitamente separado de Chaco seco 569.' });
ficha({ id:'humedales_guayaquil', nombre:'Pastizales inundables de Guayaquil', emoji:'💧', color:'#3E8B77', ids:[582], paises:['EC'], resumen:'Planicies y humedales estacionales de la cuenca baja del Guayas, sometidos a inundaciones, sedimentación y una estación seca marcada.', vegetacion:'Herbazales inundables, pantanos, bosques ribereños y transiciones a bosque seco y manglar.', fauna:'Aves acuáticas, iguanas, peces estacionales, anfibios y pequeños mamíferos de humedal.', suelos:'Aluviales finos, arcillosos e hidromorfos; alta fertilidad potencial pero anoxia, salinidad y compactación limitan el uso.', especies:['Totora','Lechuguín','Guachapelí','Samán','Gramíneas palustres'], fuentes:[...BASE,src('MAATE Ecuador — conservación de ecosistemas nativos',URL.ecuadorBosque)], notas:'Agrega ECO_ID 582.' });
ficha({ id:'humedales_orinoco', nombre:'Humedales del Orinoco', emoji:'🦆', color:'#2F887D', ids:[583], paises:['CO','VE'], resumen:'Complejo de esteros, lagunas, sabanas inundables y bosques ribereños regido por el pulso anual del Orinoco y sus tributarios.', vegetacion:'Herbazales acuáticos, morichales, bosques de galería y vegetación flotante; comunidades cambian con profundidad y duración del agua.', fauna:'Caimán del Orinoco, tonina, manatí, chigüiro, anaconda, peces migratorios y aves acuáticas.', suelos:'Aluviales e hidromorfos con periodos de anoxia y desecación; sedimentos y conectividad lateral sostienen productividad.', especies:['Moriche','Congrio','Bora','Paspalum inundable','Victoria amazónica'], fuentes:[...BASE,src('FAO Colombia — pesca artesanal en Orinoco y Amazonía',URL.pescaColombia)], notas:'Agrega ECO_ID 583; no se activa saber pesquero por ecorregión completa.' });
ficha({ id:'pantanal', nombre:'Pantanal', emoji:'🐊', color:'#3B8D75', ids:[584], paises:['BO','BR','PY'], resumen:'Una de las mayores planicies inundables continentales, donde el pulso del río Paraguay conecta sabanas, bosques, lagunas y canales.', vegetacion:'Campos inundables, cambarazales, carandazales, capões boscosos, vegetación acuática y bosques ribereños.', fauna:'Jaguar, ciervo de los pantanos, nutria gigante, yacarés, tuiuiú y enorme diversidad de peces.', suelos:'Sedimentos aluviales jóvenes, con hidromorfía, anoxia y fertilidad espacialmente variable; el microrelieve controla duración de la inundación.', especies:['Carandá','Cambarà','Paratudo','Aguapé','Ipê-amarelo'], fuentes:[...sourceGroups.brazil,src('ICMBio — Pantanal', 'https://www.gov.br/icmbio/pt-br/assuntos/biodiversidade/unidade-de-conservacao/unidades-de-biomas/pantanal/pantanal')], notas:'Prioridad 1. Agrega ECO_ID 584.' });
ficha({ id:'humedales_parana_mesopotamia', nombre:'Humedales del Paraná y Mesopotamia', emoji:'🌊', color:'#3D8973', ids:[585,586], paises:['AR','BR','PY','UY'], resumen:'Planicies, islas, esteros y sabanas inundables del Paraná medio e inferior y la Mesopotamia, modeladas por crecientes y estiajes.', vegetacion:'Pajonales, camalotales, juncales, bosques de sauce y aliso de río, palmares y selvas en galería.', fauna:'Carpincho, ciervo de los pantanos, lobito de río, yacaré, peces migratorios y aves acuáticas.', suelos:'Aluviales jóvenes e hidromorfos, continuamente redistribuidos; albardones bien drenados alternan con bajos anóxicos.', especies:['Sauce criollo','Aliso de río','Irupé','Camalote','Pindó'], fuentes:sourceGroups.conoSur, notas:'Agrega 585 y 586; la dinámica fluvial es la condición dominante.' });
ficha({ id:'puna_seca_central', nombre:'Puna seca central', emoji:'🏔️', color:'#9A7A55', ids:[587], paises:['AR','BO','CL','PE'], resumen:'Altiplano frío y muy árido con grandes amplitudes térmicas, salares y vegetación rala concentrada alrededor de humedales.', vegetacion:'Tolares, pajonales abiertos, yaretales y bofedales muy localizados junto a manantiales y cursos de agua.', fauna:'Vicuña, suri, flamencos altoandinos, vizcacha y zorro culpeo.', suelos:'Aridisoles pedregosos, salinos o volcánicos, con poca materia orgánica; vegas y bofedales tienen suelos orgánicos frágiles.', especies:['Tola','Yareta','Ichu','Queñoa','Distichia muscoides'], fuentes:sourceGroups.andes, notas:'Reemplaza puna_altoandino en ECO_ID 587 para separar el extremo seco.' });
ficha({ id:'puna_humeda_central', nombre:'Puna húmeda central', emoji:'💧', color:'#668C61', ids:[589], paises:['BO','PE'], resumen:'Pastizales altoandinos fríos con lluvias estivales mayores, lagunas, turberas y redes de bofedales que almacenan agua.', vegetacion:'Pajonales densos de ichu, céspedes, bofedales, tolares y bosques relictos de queñoa.', fauna:'Vicuña, taruca, zambullidor del Titicaca, flamencos, vizcachas y aves de humedal.', suelos:'Suelos minerales fríos alternan con turbas y horizontes orgánicos saturados; el drenaje o pisoteo concentrado degrada lentamente los bofedales.', especies:['Ichu','Queñoa','Puya raimondii','Distichia','Oxychloe'], fuentes:sourceGroups.andes, notas:'Reemplaza puna_altoandino en ECO_ID 589.' });
ficha({ id:'paramos_andinos', nombre:'Páramos de los Andes del norte', emoji:'🌧️', color:'#557B69', ids:[590,591,593,594], paises:['CO','EC','VE'], resumen:'Ecosistemas fríos y muy húmedos por encima del bosque andino, con niebla, lluvias abundantes y suelos que regulan agua; no son puna árida.', vegetacion:'Pajonales, frailejonales, chuscales, matorrales, turberas, humedales y bosques achaparrados.', fauna:'Oso andino, danta de montaña, venados, cóndor, colibríes y anfibios endémicos.', suelos:'Andisoles y suelos orgánicos profundos, fríos y de alta capacidad de retención; drenaje, quema o labranza pueden liberar carbono y perder regulación hídrica.', especies:['Frailejones','Chusquea','Calamagrostis','Polylepis','Puya'], fuentes:sourceGroups.andes, notas:'Prioridad 1. Agrega cuatro ECO_ID y corrige la confusión previa con puna por altitud.' });
ficha({ id:'matorrales_xericos_caribe_suramericano', nombre:'Matorrales xerófilos del Caribe suramericano', emoji:'🌵', color:'#B0804F', ids:[597,602,603,606], paises:['CO','VE'], resumen:'Cardonales y matorrales áridos de la costa caribeña de Colombia y Venezuela, bajo lluvias escasas, alta evaporación y vientos salinos.', vegetacion:'Cactáceas columnares, cujíes, dividivis, agaves, bromelias terrestres y herbazales efímeros.', fauna:'Cardenal guajiro, iguanas, lagartijas, zorros, murciélagos nectarívoros y aves marinas costeras.', suelos:'Aridisoles someros, pedregosos o arenosos, frecuentemente salinos; costras y dunas son sensibles al tránsito.', especies:['Cardón','Cují','Dividivi','Agave cocui','Melocactus'], fuentes:sourceGroups.secoNorte, notas:'Agrega Araya-Paria, Guajira-Barranquilla, La Costa y Paraguaná; ECO_ID 599 sigue reservado al Caribe insular.' });
ficha({ id:'manglares_amazon_orinoco_caribe_sur', nombre:'Manglares del Amazonas, Orinoco y Caribe sur', emoji:'🌊', color:'#156B5A', ids:[611], paises:['BR','CO','GF','GY','SR','VE'], resumen:'Manglares y humedales mareales de grandes deltas y costas sedimentarias del norte sudamericano, modulados por agua dulce, sedimentos y salinidad.', vegetacion:'Bosques de mangle rojo, negro, blanco y botoncillo, marismas, planicies de marea y bosques pantanosos tierra adentro.', fauna:'Manatí, caimanes, nutrias, cangrejos, moluscos, peces juveniles, ibis y garzas.', suelos:'Lodos finos anóxicos, salobres y ricos en carbono; dependen del intercambio mareal y del aporte fluvial.', especies:['Mangle rojo','Mangle negro','Mangle blanco','Botoncillo','Mora de pantano'], fuentes:[...BASE,src('Guyana — sistema oficial de manglares','https://www.mangroves.gov.gy/about/')], notas:'Agrega ECO_ID 611. No transferir reglas de pesca o recolección entre países.' });
ficha({ id:'manglares_pacifico_suramericano', nombre:'Manglares del Pacífico suramericano', emoji:'🦀', color:'#157367', ids:[615], paises:['CO','EC','PE'], resumen:'Manglares tropicales del Pacífico de Colombia, Ecuador y extremo norte peruano, sobre estuarios lluviosos o estacionales y amplias planicies de marea.', vegetacion:'Mangle rojo de gran porte en el norte húmedo, mangle negro, blanco y jelí; canales, playones y bosque de guandal asociado.', fauna:'Piangua, cangrejos, camarones, peces juveniles, garzas, pelícanos y mamíferos costeros.', suelos:'Sedimentos mareales blandos, anóxicos y salinos con alto carbono; la elevación centimétrica cambia inundación y especie dominante.', especies:['Mangle rojo','Mangle negro','Mangle blanco','Jelí','Nato'], fuentes:[...BASE,src('FAO — derechos y pesquería de concha en manglares de Ecuador',URL.manglarEcuador)], notas:'Agrega ECO_ID 615; conocimientos de conchería requieren asociaciones y polígonos autorizados.' });
ficha({ id:'manglares_atlantico_sur_brasil', nombre:'Manglares del Atlántico sur de Brasil', emoji:'🌊', color:'#247567', ids:[616], paises:['BR'], resumen:'Manglares subtropicales y tropicales del litoral atlántico sur brasileño, ligados a estuarios, lagunas y planicies de marea.', vegetacion:'Mangle rojo, negro y blanco con marismas y bosques de restinga adyacentes; menor porte hacia el límite austral.', fauna:'Cangrejo uçá, ostras, peces juveniles, garzas, martines pescadores y mamíferos estuarinos.', suelos:'Lodos salobres anóxicos con abundante materia orgánica; relleno, canalización y pérdida de mareas degradan rápidamente el sistema.', especies:['Mangle rojo','Mangle negro','Mangle blanco','Cangrejo uçá','Spartina'], fuentes:sourceGroups.brazil, notas:'Agrega ECO_ID 616; no confundir con restinga arenosa.' });
ficha({ id:'bosque_juan_fernandez', nombre:'Bosques templados de Juan Fernández', emoji:'🏝️', color:'#326F55', ids:[560], paises:['CL'], resumen:'Bosques insulares templados oceánicos de origen volcánico, extraordinariamente endémicos y vulnerables a invasoras y erosión.', vegetacion:'Bosques siempreverdes, matorrales y helechales con numerosas plantas exclusivas del archipiélago.', fauna:'Picaflor de Juan Fernández, cachudito de Juan Fernández, fardelas y lobo fino de Juan Fernández.', suelos:'Suelos volcánicos en pendientes abruptas, húmedos pero muy erosionables cuando invasoras, incendios o herbívoros eliminan cobertura.', especies:['Luma de Juan Fernández','Chonta de Juan Fernández','Cuminia','Juan bueno','Pangue insular'], fuentes:sourceGroups.islasChile, notas:'Auditoría insular. Agrega ECO_ID 560 con ficha propia; no agrupar con bosque valdiviano continental.' });
ficha({ id:'islas_desventuradas', nombre:'Islas Desventuradas: matorral oceánico', emoji:'🏝️', color:'#6F8060', ids:[562], paises:['CL'], resumen:'Islas volcánicas hiperaisladas de San Félix y San Ambrosio, con vegetación terrestre escasa, endémica y condicionada por aridez oceánica.', vegetacion:'Matorral bajo, herbazales y plantas rupícolas en grietas y laderas; cobertura muy discontinua.', fauna:'Aves marinas nidificantes, lagartijas endémicas e invertebrados insulares; el entorno marino concentra gran diversidad.', suelos:'Suelos volcánicos someros, secos y expuestos a viento, sal y erosión; depósitos de guano aportan nutrientes localmente.', especies:['Thamnoseris','Sanambrosia','Atriplex insular','Helechos rupícolas','Liquenes'], fuentes:sourceGroups.islasChile, confianza:'media', notas:'Auditoría insular. Agrega ECO_ID 562; información terrestre limitada y sin saberes territoriales publicables.' });
ficha({ id:'isla_malpelo_xerica', nombre:'Isla Malpelo: roca oceánica xerófila', emoji:'🪨', color:'#77776D', ids:[604], paises:['CO'], resumen:'Pequeña isla volcánica oceánica, rocosa y aislada, con vegetación terrestre mínima sostenida por lluvia, niebla y nutrientes de aves marinas.', vegetacion:'Parches de helechos, líquenes y vegetación herbácea baja en grietas e islotes.', fauna:'Piquero de Nazca, lagartos y cangrejo terrestre endémicos; el sistema terrestre depende fuertemente de aportes marinos.', suelos:'Prácticamente ausentes; detritos y guano se acumulan en fisuras de roca volcánica.', especies:['Pityrogramma dealbata','Líquenes Caloplaca','Anolis agassizi','Diploglossus millepunctatus','Cangrejo de Malpelo'], fuentes:sourceGroups.malpelo, notas:'Auditoría insular. Agrega ECO_ID 604; no presentar como terreno agrícola.' });
ficha({ id:'galapagos_matorral_xerico', nombre:'Galápagos: zonas áridas y de transición', emoji:'🐢', color:'#8B8350', ids:[601], paises:['EC'], resumen:'Ecosistemas volcánicos insulares cuya zonación va de litoral y matorral árido a transiciones húmedas; RESOLVE los representa con un único ECO_ID xerófilo.', vegetacion:'Palo santo, cactus Opuntia y lava, matorral de transición; en islas altas aparecen zonas húmedas de Scalesia que el ECO_ID no separa.', fauna:'Tortugas gigantes, iguanas terrestres, pinzones de Darwin, sinsontes y reptiles endémicos.', suelos:'Suelos volcánicos jóvenes y discontinuos; cenizas más desarrolladas en zonas altas húmedas, roca desnuda y costras en zonas áridas.', especies:['Opuntia de Galápagos','Palo santo','Scalesia','Cactus de lava','Tortuga gigante'], fuentes:sourceGroups.galapagos, notas:'Auditoría fuera de la caja continental. Agrega ECO_ID 601, pero la UI debe advertir que RESOLVE no separa las zonas húmedas insulares.' });
ficha({ id:'rapa_nui_bosque_subtropical_transformado', nombre:'Rapa Nui y Sala y Gómez', emoji:'🗿', color:'#657A4B', ids:[628], paises:['CL'], resumen:'Islas subtropicales extremadamente aisladas del Pacífico suroriental; la vegetación actual de Rapa Nui está profundamente transformada y no equivale a un bosque intacto.', vegetacion:'Pastizales y matorrales secundarios dominan Rapa Nui; persisten helechos, especies costeras y programas de restauración de flora nativa. Sala y Gómez es roca oceánica con aves marinas.', fauna:'Aves marinas, reptiles e invertebrados; gran parte del endemismo terrestre histórico se perdió o está restringido.', suelos:'Volcánicos, meteorizados y muy expuestos a erosión eólica e hídrica cuando falta cobertura.', especies:['Toromiro (en restauración)','Sophora','Triumfetta semitriloba','Helechos nativos','Aves marinas'], fuentes:[...BASE,src('CONAF — Parque Nacional Rapa Nui','https://www.conaf.cl/parque_nacionales/parque-nacional-rapa-nui/')], confianza:'media', notas:'Auditoría fuera de la caja continental. Agrega ECO_ID 628; no reconstruir prácticas históricas ni sitios sagrados en la app.' });

const saberes = [];
function saber({ id, nombre, portadores, pais, territorio, ecoIds, descripcion, fuente, cautelas }) {
  saberes.push({
    id,
    nombre,
    pueblo_portadores: portadores,
    pais,
    territorio_minimo: territorio,
    ecorregiones_resolve: ecoIds,
    descripcion,
    fuente: { ...fuente, fecha_consulta: CONSULTA },
    cautelas,
    estado_geometria: 'documentado_sin_geometria',
    activacion: 'NO_AUTOMATICA: exige polígono aprobado y coincidencia espacial; país, ECO_ID o Köppen sólo filtran.',
  });
}

saber({ id:'chakra_amazonica_napo', nombre:'Chakra amazónica de Napo', portadores:'Comunidades Kichwa amazónicas; liderazgo de chakramamas', pais:'EC', territorio:'Provincia de Napo, únicamente predios y comunidades del sistema SIPAM documentado', ecoIds:[483], descripcion:'Sistema agroforestal familiar diverso que integra cultivos alimentarios, árboles, especies forestales y regeneración; conserva agrobiodiversidad y continuidad entre casa, chakra y bosque.', fuente:src('FAO GIAHS — Amazonian Chakra',URL.giahsAmazonChakra), cautelas:'No inferir composición, medicina, rituales ni calendarios. Usar el polígono oficial del SIPAM y atribución comunitaria.' });
saber({ id:'aja_shuar_amazonia_ecuatoriana', nombre:'Aja Shuar', portadores:'Mujeres y comunidades Shuar', pais:'EC', territorio:'Comunidades Shuar participantes del sur-centro amazónico ecuatoriano', ecoIds:[505], descripcion:'Huerto o sistema agroforestal biodiverso asociado a producción alimentaria, regeneración de suelo, polinizadores y cuidado territorial.', fuente:src('FAO — Guardianes del saber, la tierra y los alimentos',URL.faoGuardianes), cautelas:'La fuente documenta participantes concretos, no todo el pueblo Shuar. No publicar plantas medicinales, rituales ni localizaciones sensibles.' });
saber({ id:'chakra_andina_cotacachi', nombre:'Chakra andina de Cotacachi', portadores:'Comunidades Kichwa de Cotacachi; mujeres agricultoras', pais:'EC', territorio:'Cantón Cotacachi, sitios reconocidos por el SIPAM entre aproximadamente 2.500 y 3.400 m', ecoIds:[486,593], descripcion:'Sistema agrícola diverso que conecta pisos altitudinales y conserva variedades locales mediante parcelas familiares, redes de semillas y organización comunitaria.', fuente:src('FAO GIAHS — Chakra andina de Cotacachi',URL.giahsAndeanChakra), cautelas:'No extender a todos los Andes ecuatorianos ni publicar calendarios rituales. La delimitación SIPAM manda sobre ECO_ID.' });
saber({ id:'agricultura_andina_cusco_puno', nombre:'Agricultura andina de Cusco y Puno', portadores:'Comunidades Quechua y Aymara del corredor SIPAM', pais:'PE', territorio:'Microcuencas SIPAM de Cusco y Puno en el transecto Machu Picchu–Vilcanota–La Raya–Titicaca', ecoIds:[493,587,588,589], descripcion:'Manejo complementario de pisos, terrazas, campos elevados, pequeños reservorios y rotaciones comunales; conserva cultivos y variedades altoandinas.', fuente:src('FAO GIAHS — Andean Agriculture, Peru',URL.giahsAndesPeru), cautelas:'No convertir técnicas en receta universal ni trasladarlas fuera del sitio. Omitir sitios sagrados, rituales y calendarios.' });
saber({ id:'sistema_camellidos_norte_chile', nombre:'Ganadería camélida y agricultura altoandina del norte de Chile', portadores:'Comunidades Aymara, Quechua y Likan Antay', pais:'CL', territorio:'Sitios SIPAM de Arica y Parinacota, Tarapacá y Antofagasta, aproximadamente 3.000–4.500 m', ecoIds:[587,588,598], descripcion:'Integra camélidos, cultivos andinos y gestión comunitaria del agua con movilidad estacional adaptada a ambientes altoandinos áridos.', fuente:src('FAO GIAHS — sistema altoandino del norte de Chile',URL.giahsCamelidos), cautelas:'No publicar rutas de trashumancia, vertientes ni normas consuetudinarias. No prescribir carga animal o riego fuera del sistema.' });
saber({ id:'sistema_pehuenche_ngulumapu', nombre:'Sistema ancestral Pehuenche del Ngulumapu', portadores:'Comunidades Mapuche-Pehuenche y familias campesinas participantes', pais:'CL', territorio:'Sitios SIPAM de la cordillera Pehuenche en el sur de Chile', ecoIds:[563,595], descripcion:'Integra huertas familiares, recolección vinculada al pewen y ganadería trashumante en un paisaje de bosque y montaña.', fuente:src('FAO GIAHS — sistema Pehuenche',URL.giahsPehuenche), cautelas:'No publicar lugares de recolección, veranadas, plantas medicinales ni prácticas ceremoniales. Exige polígono SIPAM.' });
saber({ id:'agricultura_chiloe', nombre:'Agricultura de Chiloé', portadores:'Familias agricultoras chilotas y comunidades locales del sistema SIPAM', pais:'CL', territorio:'Sitios SIPAM del archipiélago de Chiloé', ecoIds:[563], descripcion:'Sistema insular diversificado centrado en variedades locales de papa, huertas y pequeña ganadería, sostenido por selección campesina e intercambio.', fuente:src('FAO GIAHS — Chiloé Agriculture',URL.giahsChiloe), cautelas:'No activar para todo el bosque valdiviano ni publicar material genético o conocimiento no autorizado.' });
