saber({ id:'quebradeiras_coco_babacu', nombre:'Quebradeiras de coco babaçu', portadores:'Movimento Interestadual das Quebradeiras de Coco Babaçu y comunidades asociadas', pais:'BR', territorio:'Comunidades documentadas en Maranhão, Tocantins, Pará y Piauí; no todo el ECO_ID', ecoIds:[540,508,518], descripcion:'Recolección y transformación integral del babaçu sostenida por conocimiento intergeneracional, organización de mujeres y defensa del acceso a palmares.', fuente:src('FAO Brasil — quebradeiras de coco y organización',URL.faoBabassu), cautelas:'No inferir derechos de acceso por presencia de palmas. Exige territorios y organizaciones reconocidas; no publicar sitios de recolección.' });
saber({ id:'chagra_amazonia_colombiana', nombre:'Chagra amazónica colombiana', portadores:'Familias y comunidades indígenas documentadas por cada proyecto', pais:'CO', territorio:'Comunidad fuente y su área de uso autorizada en Amazonas, Caquetá, Guainía, Guaviare, Putumayo o Vaupés', ecoIds:[446,473,483,503], descripcion:'Sistema agroforestal de cultivos diversos, barbechos manejados y regeneración forestal; su composición y significado dependen de cada pueblo y comunidad.', fuente:src('FAO GLIS — chagra de una comunidad amazónica colombiana',URL.faoChagra), cautelas:'No usar “chagra” como receta panamazónica. Exige fuente y consentimiento por comunidad; omitir medicina, rituales y variedades sensibles.' });
saber({ id:'gobernanza_indigena_bosque_colombia', nombre:'Gobernanza indígena de bosques amazónicos', portadores:'Organizaciones y pueblos que priorizaron proyectos del programa Visión Amazonía', pais:'CO', territorio:'Los 69 proyectos acordados en seis departamentos, sólo una vez disponibles sus polígonos públicos autorizados', ecoIds:[446,473,483,503], descripcion:'Iniciativas definidas autónomamente para gobernanza territorial, manejo forestal y bienestar, integrando conocimientos tradicionales y conservación.', fuente:src('FAO Colombia — proyectos indígenas y manejo forestal',URL.faoColombiaAmazon), cautelas:'La página no autoriza publicar límites internos ni contenidos de cada proyecto. No activar hasta contar con geometría y atribución del proponente.' });
