saber({ id:'pemon_gran_sabana', nombre:'Conocimiento territorial Pemón en Gran Sabana', portadores:'Comunidades Pemón participantes del proyecto citado por FAO', pais:'VE', territorio:'Comunidad y territorio participante en Gran Sabana, estado Bolívar', ecoIds:[570,464], descripcion:'Conservación y producción local vinculadas a paisaje de sabana y bosque, con conocimiento transmitido entre generaciones.', fuente:src('FAO — Guardianes del saber, la tierra y los alimentos',URL.faoGuardianes), cautelas:'No publicar patrones de quema, sitios sagrados, recursos medicinales ni ubicación de especies. La fuente es testimonial, no un manual.' });
saber({ id:'macushi_iwokrama_rupununi', nombre:'Manejo Macushi en Iwokrama y Rupununi', portadores:'Comunidades Macushi vinculadas a Iwokrama y áreas vecinas', pais:'GY', territorio:'Iwokrama Forest y territorios comunitarios con autorización; no toda la sabana Rupununi', ecoIds:[465,570], descripcion:'Gobernanza y uso sostenible del bosque articulados con conservación, investigación y beneficios comunitarios.', fuente:src('Guyana Protected Areas Commission — Iwokrama',URL.guyanaPac), cautelas:'No inferir usos culturales de toda persona Macushi. Exige límites comunitarios y acuerdo de la institución o comunidad.' });
