saber({ id:'kayapo_islas_bosque', nombre:'Enriquecimiento de bosque por comunidades Kayapó', portadores:'Comunidades Kayapó citadas por la literatura FAO', pais:'BR', territorio:'Tierras indígenas Kayapó donde la comunidad confirme continuidad y publicación del conocimiento', ecoIds:[507,518,567], descripcion:'Manejo y enriquecimiento de áreas forestales con especies útiles, descrito como parte de sistemas amazónicos de recursos comunes.', fuente:src('FAO — Common forest resource management',URL.faoCommons), cautelas:'Fuente histórica y secundaria: requiere validación contemporánea. No publicar especies, técnicas, sitios o calendarios como receta.' });
saber({ id:'ribeirinhos_varzea_amazonica', nombre:'Manejo ribereño de várzeas y productos forestales', portadores:'Comunidades ribeirinhas o caboclas documentadas localmente', pais:'BR', territorio:'Comunidad y tramo de várzea documentados; nunca toda la cuenca', ecoIds:[467,480,482,496], descripcion:'Sistemas diversificados que combinan pesca, cultivos de pulso fluvial, árboles y productos no maderables en mosaicos de inundación.', fuente:src('FAO Unasylva — Amazon forest dwellers',URL.faoAmazonDwellers), cautelas:'La fuente es regional e histórica. Exige verificación actual, polígono comunitario y reglas de acceso; no publicar pesqueros o plantas medicinales.' });
